using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;

namespace MyApp.Evaluation;

[TestClass]
public class ChatEvaluationTests
{
    private static ReportingConfiguration? s_reportingConfiguration;

    [AssemblyInitialize]
    public static void Initialize(TestContext context)
    {
        s_reportingConfiguration = DiskBasedReportingConfiguration.Create(
            storageRootPath: Path.Combine(context.TestRunResultsDirectory!, "eval-reports"),
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: GetChatConfiguration());
    }

    [TestMethod]
    public async Task Chat_responds_coherently_to_greeting()
    {
        await using ScenarioRun scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(TestContext.FullyQualifiedTestClassName!, TestContext.TestName!);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "Hello, how can you help me today?")
        };

        ChatResponse response = await scenarioRun.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenarioRun.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_responds_relevantly_to_factual_question()
    {
        await using ScenarioRun scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(TestContext.FullyQualifiedTestClassName!, TestContext.TestName!);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France?")
        };

        ChatResponse response = await scenarioRun.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenarioRun.EvaluateAsync(messages);
    }

    [TestMethod]
    public async Task Chat_handles_multiturn_conversation()
    {
        await using ScenarioRun scenarioRun =
            await s_reportingConfiguration!.CreateScenarioRunAsync(TestContext.FullyQualifiedTestClassName!, TestContext.TestName!);

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "I want to plan a weekend trip. Can you help?")
        };

        ChatResponse response = await scenarioRun.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        messages.Add(new ChatMessage(ChatRole.User, "I'd prefer somewhere warm with beaches."));

        response = await scenarioRun.ChatClient!.GetResponseAsync(messages);
        messages.AddRange(response.Messages);

        await scenarioRun.EvaluateAsync(messages);
    }

    public TestContext TestContext { get; set; } = null!;

    private static ChatConfiguration GetChatConfiguration()
    {
        var chatClientBuilder = new ChatClientBuilder()
            .Use(new ChatOptionsForEvaluation());

        return new ChatConfiguration(chatClientBuilder.Use(CreateChatClient()));
    }

    private static IChatClient CreateChatClient()
    {
        var endpoint = Environment.GetEnvironmentVariable("AZURE_OPENAI_ENDPOINT")
            ?? "https://localhost";
        var key = Environment.GetEnvironmentVariable("AZURE_OPENAI_API_KEY")
            ?? "test-key";

        return new Azure.AI.OpenAI.AzureOpenAIClient(
            new Uri(endpoint),
            new System.ClientModel.ApiKeyCredential(key))
            .GetChatClient("gpt-4o-mini")
            .AsIChatClient();
    }
}

file class ChatOptionsForEvaluation : DelegatingChatClient
{
    public ChatOptionsForEvaluation() : base(null!) { }

    public override async Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        options ??= new ChatOptions();
        options.Temperature = 0.1f;

        return await base.GetResponseAsync(messages, options, cancellationToken);
    }
}

